#include "ksStatePatchLoadTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StatePatchLoadTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(bool selected:{false,true})for(unsigned part=0;part<256;++part)for(unsigned seed=0;seed<256;++seed){T task(selected?T::Entry::Selected:T::Entry::Provided);unsigned reads=0,writes=0,clocks=0,children=0,bytes=0,pending=0;const unsigned storeClocks=seed&3;const auto old=uint8_t(part-1);const unsigned sourcePart=old<128?old:0;constexpr T::Child services[]{T::Child::InvalidateLive,T::Child::ExpandFields,T::Child::RefreshPart,T::Child::RefreshVoices,T::Child::RefreshSerial,T::Child::RefreshPerformance,T::Child::Context};auto read=[&](T::Read r)->unsigned{++reads;switch(r){case T::Read::SourcePart:return part;case T::Read::Target:return 0xffa33001;case T::Read::Byte:check(task.byteOffset()==bytes,"209byte source order differs");return (seed*13+task.byteOffset()*17)&255;case T::Read::Part:return seed;}return 0;};auto write=[&](T::Write w,uint8_t v){++writes;if(w==T::Write::Byte){check(task.byteOffset()==bytes&&v==((seed*13+bytes*17)&255),"Loaded byte differs");++bytes;}else{check(v==0&&bytes==209&&children==7+selected,"Pending flag cleared before services");++pending;}};
 while(!task.complete()){if(task.awaitingChild()){if(selected&&children==0)check(task.child()==T::Child::Source,"Selected source service differs");else check(task.child()==services[children-selected],"Engine refresh order differs");if(task.child()==T::Child::RefreshPart)check(task.part()==seed,"Late live part differs");++children;check(task.resumeChild(),"Load child rejected");continue;}const auto c=task.nextClocks(storeClocks),before=reads,stores=writes;check(!task.advanceBefore(c-1,read,write,storeClocks)&&reads==before&&writes==stores,"Load early read/write");check(task.advanceBefore(c,read,write,storeClocks)==c,"Load admission differs");clocks+=c;}
 const unsigned expected=208+209*(20+storeClocks)+storeClocks+(selected?68+unsigned(old>=128)*3:0);if(clocks!=expected){std::cerr<<"selected="<<selected<<" part="<<part<<" clocks="<<clocks<<" expected="<<expected<<'\n';throw std::runtime_error("Load schedule differs");}check(reads==211+selected&&writes==210&&pending==1&&children==7+selected&&(!selected||task.sourcePartOffset()==sourcePart*256)&&!task.resumeChild(),"Patch load observation/lifetime differs");++cases;}
 std::cout<<"PASS: "<<cases<<" whole selected/provided209byte loads,allbyte part selectors/clamp/stride and late data,cache/expand/engine refresh order,pending flag and exact deadlines/clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
